import functools
import inspect
from typing import ForwardRef, Any, Dict, Callable
from fastapi.dependencies.utils import get_typed_signature

def evaluate_forwardref(annotation, globalns, localns):
    if isinstance(annotation, ForwardRef):
        return eval(annotation.__forward_code__, globalns, localns)
    return annotation

def get_typed_annotation(annotation: Any, globalns: Dict[str, Any]) -> Any:
    if isinstance(annotation, str):
        annotation = ForwardRef(annotation)
        annotation = evaluate_forwardref(annotation, globalns, globalns)
    return annotation

def test_repro():
    # We need to simulate different globals.
    # We can do this by creating a function in a different module or using a trick.

    def create_original():
        class A:
            pass
        def original(a: "A"):
            return a
        return original, A

    original, A = create_original()

    # Now we wrap it.
    @functools.wraps(original)
    def wrapped(a):
        return original(a)

    # wrapped.__globals__ is the globals of this module.
    # original.__globals__ is the globals of the module where create_original was defined (this module too).
    # Wait, if they are in the same module, it's hard to reproduce.

    # Let's try to use a different module.
    import types
    module_a = types.ModuleType("module_a")
    module_a.__dict__["A"] = A

    def original_in_a(a: "A"):
        return a
    original_in_a.__globals__ = module_a.__dict__

    @functools.wraps(original_in_a)
    def wrapped_in_b(a):
        return original_in_a(a)

    # wrapped_in_b.__globals__ is current module's globals.
    # original_in_a.__globals__ is module_a's globals.

    try:
        sig = get_typed_signature(wrapped_in_b)
        print("Success: Signature obtained")
        # Check if the annotation was resolved to A
        param = list(sig.parameters.values())[0]
        if param.annotation is A:
            print("Success: Annotation resolved to A")
        else:
            print(f"Failure: Annotation resolved to {param.annotation}")
    except NameError as e:
        print(f"Failure: Caught NameError: {e}")
    except Exception as e:
        print(f"Failure: Caught exception: {type(e).__name__}: {e}")

if __name__ == "__main__":
    test_repro()
